import{_ as s,o as a,c as t,a as o}from"./app-215c512d.js";const p={};function c(e,n){return a(),t("div",null,n[0]||(n[0]=[o(`<h3 id="使用示例" tabindex="-1"><a class="header-anchor" href="#使用示例" aria-hidden="true">#</a> 使用示例</h3><h2 id="要动态生成一个表示-每周二上午-12-点-10-分执行-的-cron-表达式-可以使用-cronutils-的-cronbuilder-和-fieldexpressionfactory-来实现。" tabindex="-1"><a class="header-anchor" href="#要动态生成一个表示-每周二上午-12-点-10-分执行-的-cron-表达式-可以使用-cronutils-的-cronbuilder-和-fieldexpressionfactory-来实现。" aria-hidden="true">#</a> 要动态生成一个表示“每周二上午 12 点 10 分执行”的 Cron 表达式，可以使用 <code>CronUtils</code> 的 <code>CronBuilder</code> 和 <code>FieldExpressionFactory</code> 来实现。</h2><h3 id="_1-cron-表达式的含义" tabindex="-1"><a class="header-anchor" href="#_1-cron-表达式的含义" aria-hidden="true">#</a> 1. <strong>Cron 表达式的含义</strong></h3><p>在 Quartz 格式中，Cron 表达式由以下字段组成：</p><div class="language-text" data-ext="text"><pre class="language-text"><code>秒 分 时 日 月 周 [年]
</code></pre></div><p>对于“每周二上午 12 点 10 分执行”，对应的字段值如下：</p><ul><li><strong>秒</strong>：<code>0</code>（表示每分钟的第 0 秒触发）。</li><li><strong>分</strong>：<code>10</code>（表示每小时的第 10 分钟触发）。</li><li><strong>时</strong>：<code>12</code>（表示每天的第 12 小时触发，即中午 12 点）。</li><li><strong>日</strong>：<code>?</code>（不指定具体日期，与“周”字段互斥）。</li><li><strong>月</strong>：<code>*</code>（表示每月都触发）。</li><li><strong>周</strong>：<code>3</code>（在 Quartz 中，<code>3</code> 表示星期二，<code>1</code> 表示星期日，<code>7</code> 也表示星期日）。</li></ul><p>最终的 Cron 表达式为：</p><div class="language-text" data-ext="text"><pre class="language-text"><code>0 10 12 ? * 3
</code></pre></div><hr><h3 id="_2-动态生成-cron-表达式的代码" tabindex="-1"><a class="header-anchor" href="#_2-动态生成-cron-表达式的代码" aria-hidden="true">#</a> 2. <strong>动态生成 Cron 表达式的代码</strong></h3><p>以下是使用 <code>CronUtils</code> 动态生成该 Cron 表达式的完整代码：</p><div class="language-java" data-ext="java"><pre class="language-java"><code><span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>builder<span class="token punctuation">.</span></span><span class="token class-name">CronBuilder</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span></span><span class="token class-name">Cron</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span>definition<span class="token punctuation">.</span></span><span class="token class-name">CronDefinition</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span>definition<span class="token punctuation">.</span></span><span class="token class-name">CronDefinitionBuilder</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span>field<span class="token punctuation">.</span>expression<span class="token punctuation">.</span></span><span class="token class-name">FieldExpressionFactory</span></span><span class="token punctuation">;</span>

<span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">DynamicCronGeneration</span> <span class="token punctuation">{</span>

    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">void</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token class-name">String</span><span class="token punctuation">[</span><span class="token punctuation">]</span> args<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// 定义 Quartz 格式的 Cron</span>
        <span class="token class-name">CronDefinition</span> cronDefinition <span class="token operator">=</span> <span class="token class-name">CronDefinitionBuilder</span><span class="token punctuation">.</span><span class="token function">instanceDefinitionFor</span><span class="token punctuation">(</span><span class="token class-name">CronType</span><span class="token punctuation">.</span><span class="token constant">QUARTZ</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token comment">// 动态生成 Cron 表达式</span>
        <span class="token class-name">Cron</span> cron <span class="token operator">=</span> <span class="token class-name">CronBuilder</span><span class="token punctuation">.</span><span class="token function">cron</span><span class="token punctuation">(</span>cronDefinition<span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">withSecond</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">)</span>               <span class="token comment">// 秒：0</span>
                <span class="token punctuation">.</span><span class="token function">withMinute</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span><span class="token punctuation">)</span>              <span class="token comment">// 分：10</span>
                <span class="token punctuation">.</span><span class="token function">withHour</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token number">12</span><span class="token punctuation">)</span><span class="token punctuation">)</span>                <span class="token comment">// 时：12（中午 12 点）</span>
                <span class="token punctuation">.</span><span class="token function">withDoM</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">questionMark</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>          <span class="token comment">// 日：不指定</span>
                <span class="token punctuation">.</span><span class="token function">withMonth</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string">&quot;*&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span>              <span class="token comment">// 月：每月</span>
                <span class="token punctuation">.</span><span class="token function">withDoW</span><span class="token punctuation">(</span><span class="token class-name">FieldExpressionFactory</span><span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">)</span>                  <span class="token comment">// 周：3（星期二）</span>
                <span class="token punctuation">.</span><span class="token function">instance</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token comment">// 输出生成的 Cron 表达式</span>
        <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;生成的 Cron 表达式: &quot;</span> <span class="token operator">+</span> cron<span class="token punctuation">.</span><span class="token function">asString</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><hr><h3 id="_3-运行结果" tabindex="-1"><a class="header-anchor" href="#_3-运行结果" aria-hidden="true">#</a> 3. <strong>运行结果</strong></h3><p>运行上述代码后，输出的 Cron 表达式为：</p><div class="language-text" data-ext="text"><pre class="language-text"><code>生成的 Cron 表达式: 0 10 12 ? * 3
</code></pre></div><hr><h3 id="_4-代码解析" tabindex="-1"><a class="header-anchor" href="#_4-代码解析" aria-hidden="true">#</a> 4. <strong>代码解析</strong></h3><h4 id="_1-字段设置" tabindex="-1"><a class="header-anchor" href="#_1-字段设置" aria-hidden="true">#</a> (1) <strong>字段设置</strong></h4><ul><li><strong>秒 (<code>Second</code>)</strong>：使用 <code>FieldExpressionFactory.on(0)</code>，表示每分钟的第 0 秒触发。</li><li><strong>分 (<code>Minute</code>)</strong>：使用 <code>FieldExpressionFactory.on(10)</code>，表示每小时的第 10 分钟触发。</li><li><strong>时 (<code>Hour</code>)</strong>：使用 <code>FieldExpressionFactory.on(12)</code>，表示每天的第 12 小时（中午 12 点）触发。</li><li><strong>日 (<code>DoM</code>)</strong>：使用 <code>FieldExpressionFactory.questionMark()</code>，表示不指定具体日期（与“周”字段互斥）。</li><li><strong>月 (<code>Month</code>)</strong>：使用 <code>FieldExpressionFactory.on(&quot;*&quot;)</code>，表示每月都触发。</li><li><strong>周 (<code>DoW</code>)</strong>：使用 <code>FieldExpressionFactory.on(3)</code>，表示每周的星期二触发。</li></ul><h4 id="_2-quartz-的星期字段规则" tabindex="-1"><a class="header-anchor" href="#_2-quartz-的星期字段规则" aria-hidden="true">#</a> (2) <strong>Quartz 的星期字段规则</strong></h4><p>在 Quartz 格式中：</p><ul><li><code>1</code> 表示星期日。</li><li><code>2</code> 表示星期一。</li><li><code>3</code> 表示星期二。</li><li>...</li><li><code>7</code> 也可以表示星期日。</li></ul><p>因此，<code>3</code> 对应星期二。</p><hr><h3 id="_5-验证生成的-cron-表达式" tabindex="-1"><a class="header-anchor" href="#_5-验证生成的-cron-表达式" aria-hidden="true">#</a> 5. <strong>验证生成的 Cron 表达式</strong></h3><p>为了确保生成的 Cron 表达式正确，可以使用 Quartz 或 CronUtils 验证下一次运行时间。</p><h4 id="示例代码-验证-cron-表达式" tabindex="-1"><a class="header-anchor" href="#示例代码-验证-cron-表达式" aria-hidden="true">#</a> 示例代码：验证 Cron 表达式</h4><div class="language-java" data-ext="java"><pre class="language-java"><code><span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span></span><span class="token class-name">Cron</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span>definition<span class="token punctuation">.</span></span><span class="token class-name">CronDefinition</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span>definition<span class="token punctuation">.</span></span><span class="token class-name">CronDefinitionBuilder</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>model<span class="token punctuation">.</span>time<span class="token punctuation">.</span></span><span class="token class-name">ExecutionTime</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>cronutils<span class="token punctuation">.</span>parser<span class="token punctuation">.</span></span><span class="token class-name">CronParser</span></span><span class="token punctuation">;</span>

<span class="token keyword">import</span> <span class="token import"><span class="token namespace">java<span class="token punctuation">.</span>time<span class="token punctuation">.</span></span><span class="token class-name">ZonedDateTime</span></span><span class="token punctuation">;</span>

<span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">CronValidation</span> <span class="token punctuation">{</span>

    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">void</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token class-name">String</span><span class="token punctuation">[</span><span class="token punctuation">]</span> args<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// 定义 Quartz 格式的 Cron</span>
        <span class="token class-name">CronDefinition</span> cronDefinition <span class="token operator">=</span> <span class="token class-name">CronDefinitionBuilder</span><span class="token punctuation">.</span><span class="token function">instanceDefinitionFor</span><span class="token punctuation">(</span><span class="token class-name">CronType</span><span class="token punctuation">.</span><span class="token constant">QUARTZ</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token comment">// 创建解析器</span>
        <span class="token class-name">CronParser</span> parser <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">CronParser</span><span class="token punctuation">(</span>cronDefinition<span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token comment">// 解析 Cron 表达式</span>
        <span class="token class-name">String</span> cronExpression <span class="token operator">=</span> <span class="token string">&quot;0 10 12 ? * 3&quot;</span><span class="token punctuation">;</span> <span class="token comment">// 每周二上午 12 点 10 分</span>
        <span class="token class-name">Cron</span> cron <span class="token operator">=</span> parser<span class="token punctuation">.</span><span class="token function">parse</span><span class="token punctuation">(</span>cronExpression<span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token comment">// 获取执行时间工具</span>
        <span class="token class-name">ExecutionTime</span> executionTime <span class="token operator">=</span> <span class="token class-name">ExecutionTime</span><span class="token punctuation">.</span><span class="token function">forCron</span><span class="token punctuation">(</span>cron<span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token comment">// 当前时间</span>
        <span class="token class-name">ZonedDateTime</span> now <span class="token operator">=</span> <span class="token class-name">ZonedDateTime</span><span class="token punctuation">.</span><span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 替换为你测试的时间，例如 2023-10-09T10:00+08:00</span>

        <span class="token comment">// 计算下一次运行时间</span>
        <span class="token class-name">ZonedDateTime</span> nextExecution <span class="token operator">=</span> executionTime<span class="token punctuation">.</span><span class="token function">nextExecution</span><span class="token punctuation">(</span>now<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">orElse</span><span class="token punctuation">(</span><span class="token keyword">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;下一次运行时间: &quot;</span> <span class="token operator">+</span> nextExecution<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>运行结果（假设当前时间为 <code>2023-10-09T10:00+08:00</code>）：</p><div class="language-text" data-ext="text"><pre class="language-text"><code>下一次运行时间: 2023-10-10T12:10+08:00[Asia/Shanghai]
</code></pre></div><hr><h3 id="_6-总结" tabindex="-1"><a class="header-anchor" href="#_6-总结" aria-hidden="true">#</a> 6. <strong>总结</strong></h3><ul><li><strong>表达式生成</strong>：通过 <code>CronBuilder</code> 和 <code>FieldExpressionFactory</code> 动态生成 Cron 表达式。</li><li><strong>字段适配性</strong>： <ul><li>使用 <code>on(value)</code> 设置固定值。</li><li>使用 <code>questionMark()</code> 表示“不指定”。</li></ul></li><li><strong>验证逻辑</strong>：通过 Quartz 或 CronUtils 验证生成的表达式是否符合预期。</li></ul>`,35)]))}const i=s(p,[["render",c],["__file","cornutils.html.vue"]]);export{i as default};
